const TOTAL_STATIONS = REGIONS.reduce((s, r) => s + r.count, 0);

// Approximate region centers (used until exact per-branch coordinates are
// supplied). [lat, lng]
const REGION_CENTERS = {
  "თბილისი": [41.7151, 44.8271],
  "კახეთი": [41.9166, 45.4736],
  "ქვემო ქართლი": [41.4519, 45.0967],
  "იმერეთი": [42.2679, 42.718],
  "შიდა ქართლი": [41.9847, 44.1094],
};

// Exact [lat, lng] per branch address, once known — key must match the
// address text exactly as it appears in REGIONS above. Any address not
// listed here falls back to its region's approximate center.
const STATION_COORDS = {
  "აეროპორტის ხიდის მიმდებარედ, ისანი-სამგორი": [41.6927077, 44.9577878],
};

// Exact Google Maps links per branch address (for the "open in maps"
// button). Same keying rule as STATION_COORDS.
const MAP_LINKS = {
  "აეროპორტის ხიდის მიმდებარედ, ისანი-სამგორი": "https://maps.app.goo.gl/hE5y3NMy9K4vTfGR6",
};

function buildMapsUrl(addr, region) {
  if (MAP_LINKS[addr]) return MAP_LINKS[addr];
  return `https://www.google.com/maps/search/?api=1&query=${encodeURIComponent(`${addr}, ${region}, საქართველო`)}`;
}

function getStationCoords(addr, region) {
  return STATION_COORDS[addr] || REGION_CENTERS[region] || REGION_CENTERS["თბილისი"];
}

// Formspree form ID — recipient inboxes are configured in the Formspree
// dashboard, never present in this client code.
const ORDER_FORM_ID = "meaqgekw";

const GALLON_LOGO_SRC = "data:image/png;base64,";

function Logo({ variant = "color", size = 40 })  {
  if (variant === "white") {
    return (
      <img
        src={GALLON_LOGO_SRC}
        alt="Gallon"
        style={{ width: size, height: size, objectFit: "contain", display: "block", filter: "brightness(0) invert(1)" }}
      />
    );
  }
  return (
    <img
      src={GALLON_LOGO_SRC}
      alt="Gallon"
      style={{ width: size, height: size, objectFit: "contain", display: "block" }}
    />
  );
}

